cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <int TILE_K>
__global__ void matvec_fp16_kernel(
    const __half* __restrict__ A,
    const __half* __restrict__ B,
    __half* __restrict__ C,
    int M,
    int K)
{
    // one output element per thread (row of A)
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row >= M) return;

    float acc = 0.0f;

    // process K dimension in tiles
    for (int k = 0; k < K; k += TILE_K) {
        // load a tile of B (size TILE_K) into registers
        // use half2 for vectorized loads when possible
        #pragma unroll
        for (int t = 0; t < TILE_K; t += 2) {
            int idx = k + t;
            if (idx + 1 < K) {
                // load two half values as half2
                half2 b_vec = __halves2half2(B[idx], B[idx+1]);
                // load two A values
                half2 a_vec = __halves2half2(A[row * K + idx], A[row * K + idx + 1]);
                // convert to float and multiply‑accumulate
                acc += __half2float(a_vec.x) * __half2float(b_vec.x);
                acc += __half2float(a_vec.y) * __half2float(b_vec.y);
            } else if (idx < K) {
                // tail element
                acc += __half2float(A[row * K + idx]) * __half2float(B[idx]);
            }
        }
    }

    C[row] = __float2half(acc);
}

torch::Tensor matvec_fp16(torch::Tensor A, torch::Tensor B) {
    // A: (M, K)  half
    // B: (K, 1) half (we treat as (K,) for simplicity)
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kHalf && B.dtype() == torch::kHalf,
                "inputs must be half precision");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A must be 2‑D, B must be 2‑D");
    TORCH_CHECK(B.size(1) == 1, "B must have shape (K,1)");

    int64_t M = A.size(0);
    int64_t K = A.size(1);
    auto options = torch::TensorOptions().dtype(torch::kHalf).device(A.device());
    torch::Tensor C = torch::empty({M, 1}, options);

    const int threads = 256;
    const int blocks = (M + threads - 1) / threads;
    const int TILE_K = 64;  // must be multiple of 2 for half2 vectorization

    AT_DISPATCH_HALF_TYPES(A.scalar_type(), "matvec_fp16_kernel", ([&] {
        matvec_fp16_kernel<TILE_K><<<blocks, threads>>>(
            reinterpret_cast<const __half*>(A.data_ptr()),
            reinterpret_cast<const __half*>(B.data_ptr()),
            reinterpret_cast<__half*>(C.data_ptr()),
            static_cast<int>(M),
            static_cast<int>(K));
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }

    return C;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matvec_fp16", &matvec_fp16, "Half‑precision matrix‑vector multiply (CUDA)");
}
'''

# ----------------------------------------------------------------------
# Compile the extension
# ----------------------------------------------------------------------
matvec_ext = load_inline(name='matvec_ext',
                         cpp_sources='',
                         cuda_sources=cuda_source,
                         functions=['matvec_fp16'],
                         verbose=False)

# ----------------------------------------------------------------------
# Python wrapper module
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Expect A: (M, K) half, B: (K, 1) half on CUDA
        return matvec_ext.matvec_fp16(A, B)

# ----------------------------------------------------------------------
# Helper functions matching the reference API
# ----------------------------------------------------------------------
def get_inputs():
    M = 256 * 8          # 2048
    K = 131072 * 8       # 1,048,576
    A = torch.randn(M, K, dtype=torch.float16, device='cuda')
    B = torch.randn(K, 1, dtype=torch.float16, device='cuda')
    return [A, B]

def get_init_inputs():
    return []   # No special initialization needed

# ----------------------------------------------------------------------
# Export symbols for the test harness
# ----------------------------------------------------------------------
__all__ = ['ModelNew', 'get_inputs', 'get_init_inputs']
